do $$declare n integer;begin select count(*) into n from pg_tables where schemaname='public';if n<>39 then raise exception 'ROLLBACK_TABLE_COUNT:%',n;end if;if to_regclass('public.offers') is not null or to_regclass('public.financial_ledger_entries') is not null or to_regclass('public.notifications') is not null then raise exception 'PHASE6A_TABLE_REMAINS';end if;if exists(select 1 from information_schema.columns where table_schema='public' and table_name='sales' and column_name='buyer_user_id') then raise exception 'PHASE6A_COLUMN_REMAINS';end if;end$$;
